/**
 * Evaluates a {@link Window} operator: the argument is materialised, every distinct window specification (partition and
 * order expressions) is sorted once, partitions and peer groups are scanned, and each {@link WindowElem} is computed
 * with an algorithm linear in the partition size wherever the frame allows (ranks, cumulative frames, sliding ROWS
 * frames for sums and counts). Input solutions are emitted in their original order with the window results attached.
 */
@Experimental
public final class WindowQueryEvaluationStep implements QueryEvaluationStep {

	private enum Kind {
		ROW_NUMBER,
		RANK,
		DENSE_RANK,
		NTILE,
		LAG,
		LEAD,
		FIRST_VALUE,
		LAST_VALUE,
		NTH_VALUE,
		PERCENT_RANK,
		CUME_DIST,
		SUM,
		AVG,
		COUNT,
		MIN,
		MAX
	}

	private final QueryEvaluationStep arg;
	private final QueryEvaluationContext context;
	private final ValueFactory vf;
	private final Comparator<Value> valueComparator;
	private final List<Spec> specs = new ArrayList<>();

	/** A window specification shared by one or more computations. */
	private static final class Spec {
		final WindowFunctionCall prototype;
		final QueryValueEvaluationStep[] partitionSteps;
		final QueryValueEvaluationStep[] orderSteps;
		final boolean[] ascending;
		final List<Computation> computations = new ArrayList<>();

		Spec(WindowFunctionCall prototype, QueryValueEvaluationStep[] partitionSteps,
				QueryValueEvaluationStep[] orderSteps, boolean[] ascending) {
			this.prototype = prototype;
			this.partitionSteps = partitionSteps;
			this.orderSteps = orderSteps;
			this.ascending = ascending;
		}
	}

	private static final class Computation {
		final Kind kind;
		final WindowFunctionCall call;
		final QueryValueEvaluationStep[] argSteps;
		final BiConsumer<Value, MutableBindingSet> setter;

		Computation(Kind kind, WindowFunctionCall call, QueryValueEvaluationStep[] argSteps,
				BiConsumer<Value, MutableBindingSet> setter) {
			this.kind = kind;
			this.call = call;
			this.argSteps = argSteps;
			this.setter = setter;
		}
	}

	public WindowQueryEvaluationStep(Window window, QueryEvaluationStep arg, EvaluationStrategy strategy,
			QueryEvaluationContext context, ValueFactory vf) {
		this.arg = arg;
		this.context = context;
		this.vf = vf;
		Comparator<Value> comparator = context.getComparator();
		this.valueComparator = comparator != null ? comparator : new ValueComparator();
		for (WindowElem element : window.getElements()) {
			WindowFunctionCall call = element.getOperator();
			Kind kind = kind(call.getURI());
			Spec spec = null;
			for (Spec candidate : specs) {
				if (candidate.prototype.sameWindowSpecification(call)) {
					spec = candidate;
					break;
				}
			}
			if (spec == null) {
				QueryValueEvaluationStep[] partitionSteps = precompile(call.getPartitionBy(), strategy, context);
				QueryValueEvaluationStep[] orderSteps = new QueryValueEvaluationStep[call.getOrderBy().size()];
				boolean[] ascending = new boolean[orderSteps.length];
				for (int i = 0; i < orderSteps.length; i++) {
					OrderElem elem = call.getOrderBy().get(i);
					orderSteps[i] = strategy.precompile(elem.getExpr(), context);
					ascending[i] = elem.isAscending();
				}
				spec = new Spec(call, partitionSteps, orderSteps, ascending);
				specs.add(spec);
			}
			validate(kind, call);
			spec.computations.add(new Computation(kind, call, precompile(call.getArgs(), strategy, context),
					context.setBinding(element.getName())));
		}
	}

	private static QueryValueEvaluationStep[] precompile(List<ValueExpr> exprs, EvaluationStrategy strategy,
			QueryEvaluationContext context) {
		QueryValueEvaluationStep[] steps = new QueryValueEvaluationStep[exprs.size()];
		for (int i = 0; i < steps.length; i++) {
			steps[i] = strategy.precompile(exprs.get(i), context);
		}
		return steps;
	}

	private static Kind kind(String uri) {
		if (!uri.startsWith(WINF.NAMESPACE)) {
			throw new QueryEvaluationException("Unknown window function '" + uri + "'");
		}
		switch (uri.substring(WINF.NAMESPACE.length())) {
		case "rowNumber":
			return Kind.ROW_NUMBER;
		case "rank":
			return Kind.RANK;
		case "denseRank":
			return Kind.DENSE_RANK;
		case "ntile":
			return Kind.NTILE;
		case "lag":
			return Kind.LAG;
		case "lead":
			return Kind.LEAD;
		case "firstValue":
			return Kind.FIRST_VALUE;
		case "lastValue":
			return Kind.LAST_VALUE;
		case "nthValue":
			return Kind.NTH_VALUE;
		case "percentRank":
			return Kind.PERCENT_RANK;
		case "cumeDist":
			return Kind.CUME_DIST;
		case "sum":
			return Kind.SUM;
		case "avg":
			return Kind.AVG;
		case "count":
			return Kind.COUNT;
		case "min":
			return Kind.MIN;
		case "max":
			return Kind.MAX;
		default:
			throw new QueryEvaluationException("Unknown window function '" + uri + "'");
		}
	}

	private static void validate(Kind kind, WindowFunctionCall call) {
		int args = call.getArgs().size();
		int min;
		int max;
		switch (kind) {
		case ROW_NUMBER:
		case RANK:
		case DENSE_RANK:
		case PERCENT_RANK:
		case CUME_DIST:
			min = max = 0;
			break;
		case NTILE:
		case FIRST_VALUE:
		case LAST_VALUE:
		case SUM:
		case AVG:
		case COUNT:
		case MIN:
		case MAX:
			min = max = 1;
			break;
		case NTH_VALUE:
			min = max = 2;
			break;
		default: // LAG, LEAD
			min = 1;
			max = 3;
		}
		if (args < min || args > max) {
			throw new QueryEvaluationException(call.getURI() + " expects " + (min == max ? String.valueOf(min)
					: min + " to " + max) + " argument(s), got " + args);
		}
		if (call.getFrameMode() == FrameMode.RANGE) {
			for (Long bound : new Long[] { call.getFrameStart(), call.getFrameEnd() }) {
				if (bound != null && bound != 0) {
					throw new QueryEvaluationException(
							"RANGE frames only support unbounded and current-row bounds in " + call.getURI());
				}
			}
		}
	}

	@Override
	public CloseableIteration<BindingSet> evaluate(BindingSet bindings) {
		List<MutableBindingSet> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> input = arg.evaluate(bindings)) {
			while (input.hasNext()) {
				rows.add(context.createBindingSet(input.next()));
			}
		}
		int n = rows.size();
		if (n > 0) {
			for (Spec spec : specs) {
				compute(spec, rows);
			}
		}
		List<BindingSet> result = new ArrayList<>(rows);
		return new CloseableIteratorIteration<>(result.iterator());
	}

	private Value eval(QueryValueEvaluationStep step, BindingSet row) {
		try {
			return step.evaluate(row);
		} catch (ValueExprEvaluationException e) {
			return null;
		}
	}

	private void compute(Spec spec, List<MutableBindingSet> rows) {
		int n = rows.size();
		int partitionArity = spec.partitionSteps.length;
		int orderArity = spec.orderSteps.length;
		Value[][] partitionKeys = partitionArity == 0 ? null : new Value[n][];
		Value[][] orderKeys = orderArity == 0 ? null : new Value[n][];
		for (int i = 0; i < n; i++) {
			BindingSet row = rows.get(i);
			if (partitionKeys != null) {
				Value[] keys = new Value[partitionArity];
				for (int k = 0; k < partitionArity; k++) {
					keys[k] = eval(spec.partitionSteps[k], row);
				}
				partitionKeys[i] = keys;
			}
			if (orderKeys != null) {
				Value[] keys = new Value[orderArity];
				for (int k = 0; k < orderArity; k++) {
					keys[k] = eval(spec.orderSteps[k], row);
				}
				orderKeys[i] = keys;
			}
		}
		Integer[] order = new Integer[n];
		for (int i = 0; i < n; i++) {
			order[i] = i;
		}
		Comparator<Integer> partitionComparator = (a, b) -> compareKeys(partitionKeys[a], partitionKeys[b], null);
		if (partitionKeys != null || orderKeys != null) {
			Arrays.sort(order, (a, b) -> {
				int c = partitionKeys == null ? 0 : partitionComparator.compare(a, b);
				if (c != 0 || orderKeys == null) {
					return c;
				}
				return compareKeys(orderKeys[a], orderKeys[b], spec.ascending);
			});
		}
		// peer groups: rows with equal order keys within a partition
		int[] peerStart = new int[n];
		int[] peerEnd = new int[n];
		int start = 0;
		while (start < n) {
			int end = start + 1;
			while (end < n && (partitionKeys == null || partitionComparator.compare(order[start], order[end]) == 0)) {
				end++;
			}
			// [start, end) is one partition
			int ps = start;
			while (ps < end) {
				int pe = ps + 1;
				while (pe < end && (orderKeys == null
						|| compareKeys(orderKeys[order[ps]], orderKeys[order[pe]], spec.ascending) == 0)) {
					pe++;
				}
				for (int i = ps; i < pe; i++) {
					peerStart[i] = ps;
					peerEnd[i] = pe;
				}
				ps = pe;
			}
			for (Computation computation : spec.computations) {
				computePartition(computation, rows, order, start, end, peerStart, peerEnd, orderArity > 0);
			}
			start = end;
		}
	}

	private int compareKeys(Value[] a, Value[] b, boolean[] ascending) {
		if (a == null || b == null) {
			return 0;
		}
		for (int i = 0; i < a.length; i++) {
			int c = valueComparator.compare(a[i], b[i]);
			if (c != 0) {
				return ascending == null || ascending[i] ? c : -c;
			}
		}
		return 0;
	}

	private void computePartition(Computation computation, List<MutableBindingSet> rows, Integer[] order, int pStart,
			int pEnd, int[] peerStart, int[] peerEnd, boolean ordered) {
		int m = pEnd - pStart;
		Kind kind = computation.kind;
		switch (kind) {
		case ROW_NUMBER:
			for (int pos = pStart; pos < pEnd; pos++) {
				set(computation, rows, order, pos, integer(pos - pStart + 1));
			}
			return;
		case RANK:
			for (int pos = pStart; pos < pEnd; pos++) {
				set(computation, rows, order, pos, integer(peerStart[pos] - pStart + 1));
			}
			return;
		case DENSE_RANK: {
			long dense = 0;
			for (int pos = pStart; pos < pEnd; pos++) {
				if (peerStart[pos] == pos) {
					dense++;
				}
				set(computation, rows, order, pos, integer(dense));
			}
			return;
		}
		case PERCENT_RANK:
			for (int pos = pStart; pos < pEnd; pos++) {
				double rank = peerStart[pos] - pStart;
				set(computation, rows, order, pos, vf.createLiteral(m == 1 ? 0.0 : rank / (m - 1)));
			}
			return;
		case CUME_DIST:
			for (int pos = pStart; pos < pEnd; pos++) {
				set(computation, rows, order, pos, vf.createLiteral((double) (peerEnd[pos] - pStart) / m));
			}
			return;
		case NTILE:
			for (int pos = pStart; pos < pEnd; pos++) {
				long buckets = requirePositiveInteger(computation, rows.get(order[pos]), 0, "number of buckets");
				long i = pos - pStart;
				long base = m / buckets;
				long remainder = m % buckets;
				long bucket = i < (base + 1) * remainder ? i / (base + 1) + 1 : (i - remainder) / base + 1;
				set(computation, rows, order, pos, integer(bucket));
			}
			return;
		case LAG:
		case LEAD:
			for (int pos = pStart; pos < pEnd; pos++) {
				BindingSet row = rows.get(order[pos]);
				long offset = computation.argSteps.length > 1 ? requireNonNegativeInteger(computation, row, 1, "offset")
						: 1;
				long target = kind == Kind.LAG ? pos - offset : pos + offset;
				Value value;
				if (target >= pStart && target < pEnd) {
					value = eval(computation.argSteps[0], rows.get(order[(int) target]));
				} else {
					value = computation.argSteps.length > 2 ? eval(computation.argSteps[2], row) : null;
				}
				set(computation, rows, order, pos, value);
			}
			return;
		default:
			computeFramed(computation, rows, order, pStart, pEnd, peerStart, peerEnd, ordered);
		}
	}

	private void computeFramed(Computation computation, List<MutableBindingSet> rows, Integer[] order, int pStart,
			int pEnd, int[] peerStart, int[] peerEnd, boolean ordered) {
		int m = pEnd - pStart;
		Value[] values = new Value[m];
		for (int pos = pStart; pos < pEnd; pos++) {
			values[pos - pStart] = eval(computation.argSteps[0], rows.get(order[pos]));
		}
		WindowFunctionCall call = computation.call;
		FrameMode mode = call.getFrameMode();
		Long frameStart = call.getFrameStart();
		Long frameEnd = call.getFrameEnd();
		FrameAggregate aggregate = computation.kind == Kind.SUM || computation.kind == Kind.AVG
				|| computation.kind == Kind.COUNT ? new FrameAggregate(values) : null;
		RunningExtremum running = null;
		int previousStart = 0;
		int previousEnd = 0;
		for (int pos = pStart; pos < pEnd; pos++) {
			int i = pos - pStart;
			int fs;
			int fe;
			if (mode == null) {
				fs = 0;
				fe = ordered ? peerEnd[pos] - pStart : m;
			} else if (mode == FrameMode.ROWS) {
				fs = frameStart == null ? 0 : (int) Math.max(0, Math.min(m, i + frameStart));
				fe = frameEnd == null ? m : (int) Math.max(0, Math.min(m, i + frameEnd + 1));
			} else {
				fs = frameStart == null ? 0 : peerStart[pos] - pStart;
				fe = frameEnd == null ? m : peerEnd[pos] - pStart;
			}
			if (fe < fs) {
				fe = fs;
			}
			Value result;
			switch (computation.kind) {
			case FIRST_VALUE:
				result = fs < fe ? values[fs] : null;
				break;
			case LAST_VALUE:
				result = fs < fe ? values[fe - 1] : null;
				break;
			case NTH_VALUE: {
				long nth = requirePositiveInteger(computation, rows.get(order[pos]), 1, "position");
				long index = fs + nth - 1;
				result = index < fe ? values[(int) index] : null;
				break;
			}
			case MIN:
			case MAX: {
				boolean min = computation.kind == Kind.MIN;
				if (fs == 0 && fe >= previousEnd && (running != null || i == 0)) {
					if (running == null) {
						running = new RunningExtremum(min);
					}
					for (int k = previousEnd; k < fe; k++) {
						running.add(values[k]);
					}
					result = running.value;
				} else {
					RunningExtremum extremum = new RunningExtremum(min);
					for (int k = fs; k < fe; k++) {
						extremum.add(values[k]);
					}
					result = extremum.value;
				}
				break;
			}
			default:
				aggregate.moveTo(fs, fe, previousStart, previousEnd, i == 0);
				result = computation.kind == Kind.COUNT ? integer(aggregate.count)
						: computation.kind == Kind.SUM ? aggregate.sum() : aggregate.avg();
			}
			previousStart = fs;
			previousEnd = fe;
			set(computation, rows, order, pos, result);
		}
	}

	/** Incremental SUM/AVG/COUNT over a frame whose bounds move monotonically. */
	private final class FrameAggregate {
		private final Value[] values;
		private int start;
		private int end;
		long count;
		private long errors;
		private long integers;
		private long decimals;
		private long floating;
		private BigDecimal exactSum = BigDecimal.ZERO;

		FrameAggregate(Value[] values) {
			this.values = values;
		}

		void moveTo(int fs, int fe, int previousStart, int previousEnd, boolean first) {
			if (first || fs < start || fe < end) {
				reset();
				for (int k = fs; k < fe; k++) {
					add(values[k]);
				}
			} else {
				while (start < fs) {
					remove(values[start++]);
				}
				while (end < fe) {
					add(values[end++]);
				}
			}
			start = fs;
			end = fe;
		}

		private void reset() {
			count = errors = integers = decimals = floating = 0;
			exactSum = BigDecimal.ZERO;
		}

		private void add(Value value) {
			if (value == null) {
				return;
			}
			count++;
			Literal literal = numeric(value);
			if (literal == null) {
				errors++;
				return;
			}
			switch (literal.getCoreDatatype().asXSDDatatypeOrNull()) {
			case DOUBLE:
			case FLOAT:
				floating++;
				break;
			case DECIMAL:
				decimals++;
				exactSum = exactSum.add(literal.decimalValue());
				break;
			default:
				integers++;
				exactSum = exactSum.add(new BigDecimal(literal.integerValue()));
			}
		}

		private void remove(Value value) {
			if (value == null) {
				return;
			}
			count--;
			Literal literal = numeric(value);
			if (literal == null) {
				errors--;
				return;
			}
			switch (literal.getCoreDatatype().asXSDDatatypeOrNull()) {
			case DOUBLE:
			case FLOAT:
				floating--;
				break;
			case DECIMAL:
				decimals--;
				exactSum = exactSum.subtract(literal.decimalValue());
				break;
			default:
				integers--;
				exactSum = exactSum.subtract(new BigDecimal(literal.integerValue()));
			}
		}

		Literal sum() {
			if (errors > 0) {
				return null;
			}
			if (floating > 0) {
				// floating point values: follow SPARQL promotion exactly by summing the frame directly
				Literal total = null;
				for (int k = start; k < end; k++) {
					Literal literal = numeric(values[k]);
					if (literal != null) {
						total = total == null ? literal : MathUtil.compute(total, literal, MathOp.PLUS, vf);
					}
				}
				return total;
			}
			if (decimals > 0) {
				return vf.createLiteral(exactSum);
			}
			return vf.createLiteral(exactSum.toBigIntegerExact());
		}

		Literal avg() {
			if (errors > 0) {
				return null;
			}
			if (count == 0) {
				return integer(0);
			}
			Literal total = sum();
			return MathUtil.compute(total, integer(count), MathOp.DIVIDE, vf);
		}
	}

	private static Literal numeric(Value value) {
		if (value instanceof Literal literal) {
			CoreDatatype datatype = literal.getCoreDatatype();
			if (datatype.isXSDDatatype() && ((CoreDatatype.XSD) datatype).isNumericDatatype()) {
				return literal;
			}
		}
		return null;
	}

	private final class RunningExtremum {
		private final boolean min;
		Value value;

		RunningExtremum(boolean min) {
			this.min = min;
		}

		void add(Value candidate) {
			if (candidate == null) {
				return;
			}
			if (value == null) {
				value = candidate;
				return;
			}
			int c = valueComparator.compare(candidate, value);
			if (min ? c < 0 : c > 0) {
				value = candidate;
			}
		}
	}

	private long requirePositiveInteger(Computation computation, BindingSet row, int argIndex, String what) {
		long value = requireInteger(computation, row, argIndex, what);
		if (value <= 0) {
			throw new QueryEvaluationException(what + " for " + computation.call.getURI() + " must be positive");
		}
		return value;
	}

	private long requireNonNegativeInteger(Computation computation, BindingSet row, int argIndex, String what) {
		long value = requireInteger(computation, row, argIndex, what);
		if (value < 0) {
			throw new QueryEvaluationException(what + " for " + computation.call.getURI() + " must not be negative");
		}
		return value;
	}

	private long requireInteger(Computation computation, BindingSet row, int argIndex, String what) {
		Value value = eval(computation.argSteps[argIndex], row);
		Literal literal = numeric(value);
		if (literal == null || !((CoreDatatype.XSD) literal.getCoreDatatype()).isIntegerDatatype()) {
			throw new QueryEvaluationException(what + " for " + computation.call.getURI()
					+ " must be an integer, got " + value);
		}
		return literal.longValue();
	}

	private Literal integer(long value) {
		return vf.createLiteral(BigInteger.valueOf(value));
	}

	private static void set(Computation computation, List<MutableBindingSet> rows, Integer[] order, int pos,
			Value value) {
		if (value != null) {
			computation.setter.accept(value, rows.get(order[pos]));
		}
	}
}
